-- ============================================================
-- 后室逃生 · 账号与云存档（PostgreSQL / 腾讯云 TDSQL-C PG 版）
--
-- 与 MySQL 版的差异：
--   INT UNSIGNED AUTO_INCREMENT  →  GENERATED BY DEFAULT AS IDENTITY
--   VARBINARY(n)                 →  BYTEA
--   DATETIME(3)                  →  TIMESTAMPTZ(3)
--   TINYINT(1)                   →  BOOLEAN
--   JSON                         →  JSONB（支持索引，推荐）
--   反引号 `xxx`                 →  双引号 "xxx"
--   表级 COMMENT                 →  COMMENT ON TABLE
-- ============================================================

-- 建库（如已在控制台建好可跳过）
-- CREATE DATABASE "backrooms" ENCODING 'UTF8' LC_COLLATE='C' LC_CTYPE='C' TEMPLATE=template0;

-- ---------- 1. 账号表 ----------
CREATE TABLE IF NOT EXISTS "users" (
  "id"         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nickname"   VARCHAR(24)   NOT NULL,
  "pwd_hash"   BYTEA         NOT NULL,          -- scrypt 派生密钥，64 字节
  "pwd_salt"   BYTEA         NOT NULL,          -- 随机盐，32 字节
  "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "last_login" TIMESTAMPTZ(3)
);
CREATE UNIQUE INDEX IF NOT EXISTS "uk_users_nickname" ON "users" ("nickname");
COMMENT ON TABLE  "users"              IS '玩家账号';
COMMENT ON COLUMN "users"."pwd_hash"   IS 'scrypt 派生密钥，绝不存明文';

-- ---------- 2. 云存档表 ----------
-- 一个账号一行，payload 是整份存档的 JSONB，前端做合并，服务端只管整块存取
CREATE TABLE IF NOT EXISTS "saves" (
  "user_id"    BIGINT        NOT NULL PRIMARY KEY
                             REFERENCES "users"("id") ON DELETE CASCADE,
  "payload"    JSONB         NOT NULL,
  "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE "saves" IS '云端存档（档案 / 服装 / 结局 / 设置）';

-- ---------- 3. 在线人数表 ----------
-- 登录玩家与游客都进这张表：游客用浏览器本地生成的 anon_id
-- 前端每 30 秒心跳一次，超过 90 秒无心跳视为离开，不再计入
CREATE TABLE IF NOT EXISTS "online" (
  "sess_key"    VARCHAR(64)   NOT NULL PRIMARY KEY,   -- 登录者=usr:{id}；游客=anon:{uuid}
  "user_id"     BIGINT        REFERENCES "users"("id") ON DELETE CASCADE,
  "anon"        BOOLEAN       NOT NULL DEFAULT TRUE,  -- true=未登录游客
  "nickname"    VARCHAR(24),
  "level_label" VARCHAR(40),                          -- 当前所在层级，仅用于展示
  "last_seen"   TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "idx_online_last_seen" ON "online" ("last_seen");
COMMENT ON TABLE "online" IS '在线心跳（含未登录游客）';

-- ---------- 常用查询 ----------

-- 当前游玩人数（登录 + 未登录都算，90 秒内有心跳）
--   SELECT COUNT(*) FROM "online" WHERE "last_seen" > NOW() - INTERVAL '90 seconds';

-- 只看登录玩家
--   SELECT COUNT(*) FROM "online"
--    WHERE "anon" = FALSE AND "last_seen" > NOW() - INTERVAL '90 seconds';

-- 清理过期记录（后端定时执行，或用 pg_cron）
--   DELETE FROM "online" WHERE "last_seen" < NOW() - INTERVAL '1 hour';

-- 可选：pg_cron 自动清理（需扩展已安装）
--   CREATE EXTENSION IF NOT EXISTS pg_cron;
--   SELECT cron.schedule('clean_online', '*/10 * * * *',
--     $$DELETE FROM "online" WHERE "last_seen" < NOW() - INTERVAL '1 hour'$$);
